import{_ as e,c as o,o as r,ah as s}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Logs settings","description":"","frontmatter":{"title":"Logs settings"},"headers":[],"relativePath":"logs/settings.md","filePath":"logs/settings.md"}'),a={name:"logs/settings.md"};function n(d,t,i,g,h,l){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="logs-settings" tabindex="-1">Logs settings <a class="header-anchor" href="#logs-settings" aria-label="Permalink to &quot;Logs settings&quot;">​</a></h1><p><strong>Options → Logs</strong> collects the settings of the <a href="./general.html">Logs</a> tab. Changes apply immediately.</p><hr><h2 id="search-settings" tabindex="-1">Search Settings <a class="header-anchor" href="#search-settings" aria-label="Permalink to &quot;Search Settings&quot;">​</a></h2><p>Default search modes of the <strong>Logs</strong> tab:</p><table tabindex="0"><thead><tr><th>Option</th><th>Searches in</th></tr></thead><tbody><tr><td><strong>Search by event name</strong></td><td>Title, component, store, URL (enabled by default)</td></tr><tr><td><strong>Search by key</strong></td><td>Keys in the payload and changed paths</td></tr><tr><td><strong>Search by value</strong></td><td>Values in the payload</td></tr></tbody></table><hr><h2 id="ignore-list" tabindex="-1">Ignore list <a class="header-anchor" href="#ignore-list" aria-label="Permalink to &quot;Ignore list&quot;">​</a></h2><p>Event groups added with <strong>Ignore</strong> in the <strong>Logs</strong> tab. Events of these groups are not recorded.</p><table tabindex="0"><thead><tr><th>Column</th><th>Content</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td>Event type</td></tr><tr><td><strong>Event</strong></td><td>Group key: request (method and path), component, store, etc.</td></tr><tr><td><strong>Added</strong></td><td>Date the rule was added</td></tr></tbody></table><ul><li><strong>Log again</strong> in the row menu removes one rule.</li><li><strong>Log all again</strong> removes all rules.</li></ul><p>The same list is available from the <strong>ignored</strong> indicator in the <strong>Logs</strong> toolbar.</p><hr><h2 id="what-to-log-and-limits" tabindex="-1">What to log and limits <a class="header-anchor" href="#what-to-log-and-limits" aria-label="Permalink to &quot;What to log and limits&quot;">​</a></h2><h3 id="logged-events" tabindex="-1">Logged events <a class="header-anchor" href="#logged-events" aria-label="Permalink to &quot;Logged events&quot;">​</a></h3><p>Each group has a switch: a switched-off group is not logged at all, and already logged events stay. All groups are on by default.</p><table tabindex="0"><thead><tr><th>Group</th><th>Events</th></tr></thead><tbody><tr><td><strong>Network</strong></td><td><strong>Send request</strong> and <strong>Receive response</strong></td></tr><tr><td><strong>Props changes</strong></td><td><strong>Change props</strong></td></tr><tr><td><strong>Emits</strong></td><td><strong>Emit</strong></td></tr><tr><td><strong>Pinia changes</strong></td><td><strong>Change store</strong> (when switched on again, the store starts with a new <strong>Store snapshot</strong>)</td></tr><tr><td><strong>Store actions</strong></td><td><strong>Store action</strong></td></tr><tr><td><strong>Navigation</strong></td><td><strong>Navigation</strong></td></tr><tr><td><strong>JS errors</strong></td><td><strong>JS error</strong></td></tr></tbody></table><p>The number next to a switch shows how many events of the group are currently stored.</p><h3 id="data-size" tabindex="-1">Data size <a class="header-anchor" href="#data-size" aria-label="Permalink to &quot;Data size&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Range</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Memory budget</strong></td><td>64 MB</td><td>8 – 1024 MB</td><td>Total size of all buffered events (approximate serialized size). A network entry shared by a request and its response, and equal bodies, are counted once</td></tr><tr><td><strong>Limit event size</strong></td><td>off</td><td>—</td><td>Off: events are kept whole and nothing is cut, so an exported report can be imported with complete data</td></tr><tr><td><strong>Max event size</strong></td><td>512 KB</td><td>16 – 16 384 KB</td><td>Only with <strong>Limit event size</strong>: larger parts of an event (store snapshots, arguments, results) are dropped, network bodies are cut to this size</td></tr></tbody></table><p>When the memory budget is reached, the oldest events are dropped. <strong>Pinia changes</strong> are compacted into a <strong>Store checkpoint</strong> instead, so the remaining changes keep their <strong>Before</strong> / <strong>After</strong>; the initial state of a store and its checkpoint go last (see <a href="./general.html#how-events-are-stored">How events are stored</a>). The newest event is always kept, even if it alone exceeds the budget.</p><p>The bar under the fields shows current usage (<strong>Used X of Y</strong>); it turns orange above 90 %.</p><p>Values outside the range are corrected to the nearest bound. <strong>Defaults</strong> restores all settings of the block.</p><hr><h2 id="data-masking" tabindex="-1">Data masking <a class="header-anchor" href="#data-masking" aria-label="Permalink to &quot;Data masking {#data-masking}&quot;">​</a></h2><p>Values are masked <strong>when an event is captured</strong>, so they never reach the <strong>Logs</strong> view, exports or imports.</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Mask sensitive data</strong></td><td>Enables masking (on by default)</td></tr><tr><td><strong>Mask token-like values in any text</strong></td><td>Masks <strong>JWT</strong>, <strong>Bearer</strong> / <strong>Basic</strong> credentials and card numbers inside any string</td></tr><tr><td><strong>Key contains</strong> list</td><td>Object keys, header and parameter names containing these fragments are masked</td></tr></tbody></table><p>Default keys: <code>password</code>, <code>passwd</code>, <code>pwd</code>, <code>secret</code>, <code>token</code>, <code>authorization</code>, <code>cookie</code>, <code>apikey</code>, <code>sessionid</code>, <code>privatekey</code>, <code>creditcard</code>, <code>cardnumber</code>, <code>cvv</code>, <code>cvc</code>, <code>ssn</code>, <code>otp</code>.</p><p>Keys match case-insensitively and ignore separators (<code>api_key</code>, <code>api-key</code> and <code>apiKey</code> are the same). Fragments of <strong>4 letters or fewer</strong> must match a whole word, so <code>pwd</code> or <code>otp</code> do not mask unrelated keys.</p><p>Add your own fragments in the input under the list; remove them from the row menu. <strong>Default keys</strong> restores the default list.</p><p>Masked values are replaced with markers: <code>[MASKED]</code> for values of sensitive keys, <code>[MASKED JWT]</code> and <code>[MASKED CARD]</code> for tokens and card numbers found in text (card numbers are checked with the Luhn algorithm).</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./general.html">Working with logs</a></li><li><a href="./export.html">Export and import</a></li><li><a href="/qa-tools/docs/options/settings_management.html">Settings management</a></li></ul>',34)])])}const u=e(a,[["render",n]]);export{p as __pageData,u as default};
